import { ProjectBlueprint } from '@/types';

export const generateSRSMarkdown = (project: ProjectBlueprint): string => {
  const { srs } = project;
  
  const md = `# Software Requirements Specification

**Project:** ${srs?.documentControl?.projectName || 'N/A'}
**Version:** ${srs?.documentControl?.documentVersion || '1.0'}
**Status:** ${srs?.documentControl?.status || 'Draft'}
**Generated by:** ${srs?.documentControl?.preparedBy || 'Idea2App AI'}
**Date:** ${srs?.documentControl?.date || new Date().toLocaleDateString()}

---

## 1. Introduction

### 1.1 Purpose
${srs?.introduction?.purpose || ''}

### 1.2 Scope
${srs?.introduction?.scope || ''}

### 1.3 Intended Audience
${(srs?.introduction?.intendedAudience || []).map(a => `- ${a}`).join('\n')}

### 1.4 Product Overview
${srs?.introduction?.productOverview || ''}

### 1.5 Definitions and Acronyms
| Term | Definition |
| ---- | ---------- |
${(srs?.introduction?.definitionsAndAcronyms || []).map(d => `| **${d.term}** | ${d.definition} |`).join('\n')}

### 1.6 References
${(srs?.introduction?.references || []).map(r => `- ${r}`).join('\n')}

---

## 2. Overall Description

### 2.1 Product Perspective
${srs?.overallDescription?.productPerspective || ''}

### 2.2 Product Functions
${srs?.overallDescription?.productFunctions || ''}

### 2.3 User Classes and Characteristics
${(srs?.overallDescription?.userClassesAndCharacteristics || []).map(u => `
**Role:** ${u.role}
- **Description:** ${u.description}
- **Access Level:** ${u.accessLevel}
- **Responsibilities:**
${(u.responsibilities || []).map(r => `  - ${r}`).join('\n')}
`).join('')}

### 2.4 Operating Environment
${srs?.overallDescription?.operatingEnvironment || ''}

### 2.5 Design Constraints
${(srs?.overallDescription?.designConstraints || []).map(c => `- ${c}`).join('\n')}

### 2.6 Assumptions
${(srs?.overallDescription?.assumptions || []).map(a => `- ${a}`).join('\n')}

### 2.7 Dependencies
${(srs?.overallDescription?.dependencies || []).map(d => `- ${d}`).join('\n')}

---

## 3. System Features

${(srs?.systemFeatures || []).map((f, i) => `
### 3.${i + 1} ${f.name}
- **Description:** ${f.description}
- **Priority:** ${f.priority}
- **Related Role:** ${f.relatedRole}
`).join('')}

---

## 4. Functional Requirements

${(srs?.functionalRequirements || []).map(fr => `
### ${fr.id}: ${fr.title}
- **Description:** ${fr.description}
- **Priority:** ${fr.priority}
- **Actor:** ${fr.actor || 'System'}
${fr.preconditions?.length ? `- **Preconditions:**\n${fr.preconditions.map(p => `  - ${p}`).join('\n')}` : ''}
${fr.trigger ? `- **Trigger:** ${fr.trigger}` : ''}
${fr.mainBehavior?.length ? `- **Main Behavior:**\n${fr.mainBehavior.map((mb, i) => `  ${i + 1}. ${mb}`).join('\n')}` : ''}
${fr.alternativeFlow?.length ? `- **Alternative Flow:**\n${fr.alternativeFlow.map(af => `  - ${af}`).join('\n')}` : ''}
${fr.postconditions?.length ? `- **Postconditions:**\n${fr.postconditions.map(p => `  - ${p}`).join('\n')}` : ''}
${fr.acceptanceCriteria?.length ? `- **Acceptance Criteria:**\n${fr.acceptanceCriteria.map(ac => `  - ${ac}`).join('\n')}` : ''}
`).join('\n')}

---

## 5. Non-Functional Requirements

| ID | Category | Description |
| -- | -------- | ----------- |
${(srs?.nonFunctionalRequirements || []).map(nfr => `| **${nfr.id}** | ${nfr.category} | ${nfr.description} |`).join('\n')}

---

## 6. External Interface Requirements

### 6.1 User Interface
${srs?.interfaces?.userInterface || ''}

### 6.2 Software Interfaces
${srs?.interfaces?.softwareInterfaces || ''}

### 6.3 Hardware Interfaces
${srs?.interfaces?.hardwareInterfaces || ''}

### 6.4 Communication Interfaces
${srs?.interfaces?.communicationInterfaces || ''}

---

## 7. Data Requirements

### 7.1 Data Entities
${(srs?.dataRequirements?.dataEntities || []).map(e => `
#### ${e.name}
| Field | Type | Description |
| ----- | ---- | ----------- |
${(e.fields || []).map(f => `| \`${f.name}\` | ${f.type} | ${f.description} |`).join('\n')}
`).join('')}

### 7.2 Relationships
| Source | Relationship | Target |
| ------ | ------------ | ------ |
${(srs?.dataRequirements?.relationships || []).map(r => `| **${r.source}** | ${r.relationship} | **${r.target}** |`).join('\n')}

### 7.3 Data Policies
- **Validation:** ${srs?.dataRequirements?.dataValidation || ''}
- **Integrity:** ${srs?.dataRequirements?.dataIntegrity || ''}
- **Retention:** ${srs?.dataRequirements?.dataRetention || ''}

---

## 8. User Stories

${(srs?.userStories || []).map(us => `
### ${us.id}
**As a** ${us.role}, **I want to** ${us.action}, **so that** ${us.benefit}.
**Acceptance Criteria:**
${(us.acceptanceCriteria || []).map(ac => `- ${ac}`).join('\n')}
`).join('\n')}

---

## 9. Use Cases

${(srs?.useCases || []).map(uc => `
### ${uc.id}: ${uc.name}
- **Primary Actor:** ${uc.actor}
- **Goal:** ${uc.goal}
- **Description:** ${uc.description}
- **Trigger:** ${uc.trigger}
- **Preconditions:**
${(uc.preconditions || []).map(p => `  - ${p}`).join('\n')}
- **Main Success Scenario:**
${(uc.mainSuccessScenario || []).map((s, i) => `  ${i + 1}. ${s}`).join('\n')}
${uc.alternativeFlows?.length ? `- **Alternative Flows:**\n${uc.alternativeFlows.map(af => `  - ${af}`).join('\n')}` : ''}
${uc.exceptionFlows?.length ? `- **Exception Flows:**\n${uc.exceptionFlows.map(ef => `  - ${ef}`).join('\n')}` : ''}
- **Postconditions:**
${(uc.postconditions || []).map(p => `  - ${p}`).join('\n')}
- **Related Requirements:** ${(uc.relatedRequirements || []).join(', ')}
`).join('\n')}

---

## 10. System Architecture

${srs?.architecture?.description || ''}

### Components
${(srs?.architecture?.components || []).map(c => `- **${c.name}:** ${c.responsibility}`).join('\n')}

---

## 11. System Workflows

${(srs?.workflows || []).map(wf => `
### ${wf.name}
${(wf.steps || []).map((s, i) => `${i + 1}. ${s}`).join('\n')}
`).join('\n')}

---

## 12. Security Requirements

| ID | Category | Description |
| -- | -------- | ----------- |
${(srs?.securityRequirements || []).map(sec => `| **${sec.id}** | ${sec.category} | ${sec.description} |`).join('\n')}

---

## 13. Requirements Traceability Matrix

| Feature | User Story | Functional Requirement | Use Case | Acceptance Criteria |
| ------- | ---------- | ---------------------- | -------- | ------------------- |
${(srs?.traceability || []).map(t => `| ${t.feature} | ${t.userStory} | ${t.functionalRequirement} | ${t.useCase} | ${t.acceptanceCriteria} |`).join('\n')}

---

## 14. Verification

**Approach:** ${srs?.verification?.approach || ''}

| Requirement ID | Verification Method |
| -------------- | ------------------- |
${(srs?.verification?.methods || []).map(v => `| **${v.requirementId}** | ${v.method} |`).join('\n')}

---

## 15. Constraints

### Confirmed Constraints
${(srs?.constraints?.confirmed || []).map(c => `- ${c}`).join('\n')}

### Assumed Constraints
${(srs?.constraints?.assumed || []).map(c => `- ${c}`).join('\n')}

---

## 16. Assumptions and Dependencies

### Assumptions
${(srs?.assumptions || []).map(a => `- **${a.id}:** ${a.description}`).join('\n')}

### Dependencies
${(srs?.dependencies || []).map(d => `- **${d.id}:** ${d.description}`).join('\n')}

---

## 17. Future Enhancements

${(srs?.futureEnhancements || []).map(fe => `- ${fe}`).join('\n')}

---

## 18. Appendices

${(srs?.appendices || []).map(app => `
### ${app.title}
${app.content}
`).join('\n')}

`;

  return md;
};

